catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) {
        g_form.setMandatory('related_appointment', true);
        g_form.setReadOnly('requested_for', true);
        g_form.setReadOnly('hospital', true);
        g_form.setReadOnly('contact_name', true);
        g_form.setReadOnly('contact_phone', true);
        return;
    }

    if (!newValue) {
        // Jab appointment clear / empty kar diya jaye
        g_form.setMandatory('related_admission', true);
        g_form.setDisplay('related_admission', true);
        g_form.clearValue('hospital');
        g_form.clearValue('requested_for');
        g_form.clearValue('contact_name');
        g_form.clearValue('contact_phone');
        return;
    }

    // Jab appointment select ho jaye
    g_form.setMandatory('related_admission', false);
    g_form.setDisplay('related_admission', false);

    g_form.getReference('related_appointment', function(appt) {
        if (!appt) {
            return;
        }

        // Appointment record se values le kar current form mein set karein
        // Apne appointment table ke actual field names zaroor check kar lein
        if (appt.hospital) {
            g_form.setValue('hospital', appt.hospital);
            g_form.setReadOnly('hospital', true);
        }

        // Agar appointment table par patient/requested_for field hai:
        if (appt.patient) { // ya appt.requested_for — apne table ke field name ke hisaab se badlein
            g_form.setValue('requested_for', appt.patient);
            g_form.setReadOnly('requested_for', true);
        }

        g_form.setReadOnly('contact_name', true);
        g_form.setReadOnly('contact_phone', true);
    });
}
